def topo(nodes, edges):
    # Build adjacency list and in-degree map
    # edges are (prerequisite, dependent) meaning prerequisite -> dependent
    # We need to process nodes in topological order: prerequisites before dependents

    # Normalize nodes to a set for quick lookup
    node_set = set(nodes)

    # Check that all edges reference valid nodes
    for u, v in edges:
        if u not in node_set or v not in node_set:
            raise ValueError("Edge references a node not in nodes")

    # Build adjacency list and in-degree
    # For each edge (u, v), u is prerequisite, v is dependent
    # So u must come before v in topological order
    # We add edge u -> v in the graph, and increment in-degree of v
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Use a set to ignore duplicate edges
    seen_edges = set()
    for u, v in edges:
        if (u, v) in seen_edges:
            continue
        seen_edges.add((u, v))
        adj[u].append(v)
        in_degree[v] += 1

    # Use a min-heap (priority queue) to always pick the lexicographically smallest node
    import heapq
    heap = []
    for node in nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result
