def merge_patch(target, patch):
    """
    Apply a JSON Merge Patch (RFC 7396) to a target object.

    Args:
        target: The target object to patch.
        patch: The patch to apply.

    Returns:
        The patched object.
    """
    # If patch is None, return None (replace target with null)
    if patch is None:
        return None

    # If patch is not a dict, replace target with patch
    if not isinstance(patch, dict):
        return patch

    # If target is not a dict, start with an empty dict
    if not isinstance(target, dict):
        target = {}

    # Create a copy of target to avoid mutation
    result = target.copy()

    # Process each key in the patch
    for key, value in patch.items():
        if value is None:
            # Delete the key if it exists
            if key in result:
                del result[key]
        else:
            # Recursively merge if both target and patch values are dicts
            if isinstance(value, dict) and key in result and isinstance(result[key], dict):
                result[key] = merge_patch(result[key], value)
            else:
                # Otherwise, replace the value
                result[key] = value

    return result
